def compute(vars):
    lower = vars["v1"]
    upper = vars["v2"]
    value = upper - lower
    return {
        "value": value,
        "trace": {
            "lower_bound": lower,
            "upper_bound": upper,
            "range": value,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "feet"
            }
        }
    }
